@startuml

class City {
  + Name : string
}

class H2SLocation {
  + Name : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + Description : string
  + RequestedDate : date
  + RequestedTime : time
}

class Item {
  + Description : string
  + Dimensions : string
  + Weight : float
}

class Vehicle {
  + StorageSpace : float
}

class VolunteerDriver {
  + AvailableDays : string[]
}

class PickupRoute {
  + Date : date
}

class DistributionCenter {
}

class SecondHandArticle {
  + RFID : string
  + Category : string
}

class NonPerishableFood {
}

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

class H2SEmployee {
}

City "1" *-- "1..*" H2SLocation
H2SLocation "1" *-- "1" DistributionCenter

Resident "1" -- "*" PickupRequest
PickupRequest "1" *-- "1..*" Item

VolunteerDriver "1" -- "*" PickupRoute
Vehicle "1" -- "*" PickupRoute

PickupRoute "1" -- "*" PickupRequest

Item "1" -- "0..1" SecondHandArticle
Item "1" -- "0..1" NonPerishableFood

SecondHandArticle "*" -- "1" DistributionCenter
NonPerishableFood "*" -- "1" DistributionCenter

H2SEmployee "1" -- "*" SecondHandArticle : examines
H2SEmployee "1" -- "*" Client : calls
H2SEmployee "1" -- "*" Client : arrangesDelivery

Client "1" -- "*" SecondHandArticle : receives

@enduml

